import React, { useState } from 'react';
import { View, Modal, TouchableOpacity, ScrollView, TextInput, Alert } from 'react-native';
import { AppText, AppIcon, AppButton } from '@esparex/mobile-ui';
import { REPORT_REASON, ReportReasonValue } from '@esparex/contracts';
import { services } from '../../../../../bootstrap';

interface ReportAdModalProps {
  visible: boolean;
  adId: string;
  adTitle: string;
  onClose: () => void;
}

const REPORT_REASONS: Array<{ label: string; value: ReportReasonValue }> = [
  { label: 'Fraudulent or Scam', value: REPORT_REASON.SCAM },
  { label: 'Inappropriate Content', value: REPORT_REASON.OFFENSIVE_CONTENT },
  { label: 'Spam', value: REPORT_REASON.SPAM },
  { label: 'Prohibited Item', value: REPORT_REASON.PROHIBITED_ITEM },
  { label: 'Misleading Information', value: REPORT_REASON.MISLEADING_INFO },
  { label: 'Sold Item Still Listed', value: REPORT_REASON.SOLD_ELSEWHERE },
  { label: 'Other', value: REPORT_REASON.OTHER },
];

export const ReportAdModal = ({ visible, adId, adTitle, onClose }: ReportAdModalProps) => {
  const [selectedReason, setSelectedReason] = useState<ReportReasonValue | null>(null);
  const [description, setDescription] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!selectedReason) {
      Alert.alert('Required', 'Please select a reason for reporting this listing.');
      return;
    }

    setIsSubmitting(true);
    try {
      await services.listingService.reportListing(adId, selectedReason, description.trim() || undefined);
      Alert.alert('Report Submitted', 'Thank you. Our moderation team will review this listing.', [
        {
          text: 'OK',
          onPress: () => {
            setSelectedReason(null);
            setDescription('');
            onClose();
          },
        },
      ]);
    } catch (error) {
      Alert.alert('Error', 'Unable to submit report at this time. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent
      onRequestClose={onClose}
    >
      <View className="flex-1 bg-black/60 justify-end">
        <View className="bg-white dark:bg-slate-900 rounded-t-3xl p-5 max-h-[85%]">
          {/* Header */}
          <View className="flex-row items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800 mb-4">
            <View className="flex-row items-center flex-1 mr-2">
              <View className="mr-2">
                <AppIcon name="AlertTriangle" size={20} color="#ef4444" />
              </View>
              <AppText variant="h3" className="text-slate-900 dark:text-white font-bold" numberOfLines={1}>
                Report Listing
              </AppText>
            </View>
            <TouchableOpacity
              onPress={onClose}
              disabled={isSubmitting}
              className="p-1 rounded-full bg-slate-100 dark:bg-slate-800"
              accessibilityRole="button"
              accessibilityLabel="Close report dialog"
            >
              <AppIcon name="X" size={18} color="#64748b" />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-3">
              Why are you reporting &quot;{adTitle}&quot;?
            </AppText>

            {/* Reasons list */}
            <View className="gap-2 mb-4">
              {REPORT_REASONS.map((item) => {
                const isSelected = selectedReason === item.value;
                return (
                  <TouchableOpacity
                    key={item.value}
                    onPress={() => setSelectedReason(item.value)}
                    activeOpacity={0.7}
                    className={`p-3 rounded-xl border flex-row items-center justify-between mb-1.5 ${
                      isSelected
                        ? 'border-sky-600 bg-sky-50 dark:bg-sky-950/40'
                        : 'border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/60'
                    }`}
                  >
                    <AppText
                      variant="body"
                      className={`text-sm font-medium ${
                        isSelected
                          ? 'text-sky-700 dark:text-sky-300 font-semibold'
                          : 'text-slate-700 dark:text-slate-300'
                      }`}
                    >
                      {item.label}
                    </AppText>
                    <View
                      className={`w-4 h-4 rounded-full border items-center justify-center ${
                        isSelected ? 'border-sky-600 bg-sky-600' : 'border-slate-400'
                      }`}
                    >
                      {isSelected && <View className="w-1.5 h-1.5 rounded-full bg-white" />}
                    </View>
                  </TouchableOpacity>
                );
              })}
            </View>

            {/* Additional details */}
            <AppText variant="caption" className="text-slate-600 dark:text-slate-300 font-semibold mb-1.5">
              Additional Details (Optional)
            </AppText>
            <TextInput
              value={description}
              onChangeText={setDescription}
              placeholder="Provide details to help us investigate..."
              placeholderTextColor="#94a3b8"
              multiline
              numberOfLines={3}
              className="p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm min-h-[72px] text-top mb-5"
            />

            {/* Action buttons */}
            <View className="flex-row gap-3 pb-4">
              <View className="flex-1">
                <AppButton
                  variant="outline"
                  label="Cancel"
                  onPress={onClose}
                  disabled={isSubmitting}
                />
              </View>
              <View className="flex-1">
                <AppButton
                  variant="primary"
                  label={isSubmitting ? 'Submitting...' : 'Submit Report'}
                  onPress={handleSubmit}
                  disabled={isSubmitting || !selectedReason}
                />
              </View>
            </View>
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
};

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { FlatList, RefreshControl, View, Image, TouchableOpacity } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Screen, Container, AppText, AppIcon } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import { ListingQueryParams, LocationMeta } from '@esparex/contracts';
import { useListings } from '../hooks/useListings';
import { useSavedListings } from '../hooks/useSavedListings';
import { useToggleSaveListing } from '../hooks/useToggleSaveListing';
import { useAuth } from '../../../../providers/AuthProvider';
import { ListingCard } from '../components/ListingCard';
import { ListingSkeleton } from '../components/ListingSkeleton';
import { MarketplaceHeader } from '../components/MarketplaceHeader';
import { SearchBar } from '../components/SearchBar';
import { CategoryChips } from '../components/CategoryChips';
import { LocationSelectorModal } from '../components/LocationSelectorModal';
import { EmptyState } from '../../../common/components/EmptyState';
import { ErrorState } from '../../../common/components/ErrorState';
import { navigate } from '../../../../navigation/navigationRef';
import { ROUTES } from '../../../../navigation/routes';
import { Listing } from '../../domain/Listing';

export const MarketplaceScreen = () => {
  const insets = useSafeAreaInsets();
  const [filters, setFilters] = useState<ListingQueryParams>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [isLocationModalOpen, setIsLocationModalOpen] = useState(false);
  const [selectedLocationDisplay, setSelectedLocationDisplay] = useState('All India');

  let authStatus = 'authenticated';
  try {
    const auth = useAuth();
    authStatus = auth.status;
  } catch {
    authStatus = 'authenticated';
  }

  const { data: savedListings } = useSavedListings(authStatus === 'authenticated');
  const toggleSaveMutation = useToggleSaveListing();

  const savedAdIdSet = useMemo(
    () => new Set((savedListings || []).map((s) => s.id)),
    [savedListings],
  );

  // Debounced search query updating filters
  useEffect(() => {
    const handler = setTimeout(() => {
      setFilters((prev) => ({
        ...prev,
        search: searchQuery.trim() || undefined,
        page: 1,
      }));
    }, 400);

    return () => clearTimeout(handler);
  }, [searchQuery]);

  const {
    data,
    isLoading,
    isError,
    refetch,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useListings(filters);

  const handleSelectCategory = useCallback((categoryId?: string) => {
    setFilters((prev) => ({
      ...prev,
      categoryId,
      page: 1,
    }));
  }, []);

  const handleSelectLocation = useCallback((location: LocationMeta | null) => {
    if (location) {
      const locId = location.locationId || (location as { _id?: string })._id || location.name;
      setFilters((prev) => ({
        ...prev,
        locationId: locId,
        page: 1,
      }));
      setSelectedLocationDisplay(location.display || location.city || location.name || 'Selected Location');
    } else {
      setFilters((prev) => ({
        ...prev,
        locationId: undefined,
        page: 1,
      }));
      setSelectedLocationDisplay('All India');
    }
  }, []);

  const handlePress = useCallback((id: string) => {
    navigate(ROUTES.MAIN_STACK, {
      screen: ROUTES.LISTING_DETAILS,
      params: { id },
    });
  }, []);

  const handleToggleSave = useCallback(
    (id: string) => {
      if (authStatus !== 'authenticated') {
        navigate(ROUTES.AUTH_STACK);
        return;
      }
      const isSaved = savedAdIdSet.has(id);
      toggleSaveMutation.mutate({ adId: id, isSaved });
    },
    [authStatus, savedAdIdSet, toggleSaveMutation],
  );

  const renderItem = useCallback(
    ({ item }: { item: Listing }) => (
      <ListingCard
        listing={item}
        onPress={handlePress}
        isSaved={savedAdIdSet.has(item.id)}
        onToggleSave={handleToggleSave}
      />
    ),
    [handlePress, savedAdIdSet, handleToggleSave],
  );

  const keyExtractor = useCallback((item: Listing) => item.id, []);

  const listings = useMemo(() => data?.pages.flat() || [], [data?.pages]);

  if (isError) {
    return (
      <Screen>
        <ErrorState onRetry={refetch} />
      </Screen>
    );
  }

  return (
    <Screen edges={['top', 'left', 'right']}>
      <Container padded={false} className="flex-1">
        {/* Brand & Location Header */}
        <MarketplaceHeader
          selectedLocationDisplay={selectedLocationDisplay}
          onOpenLocationModal={() => setIsLocationModalOpen(true)}
        />

        {/* Quick Search Bar */}
        <SearchBar
          value={searchQuery}
          onChangeText={setSearchQuery}
          onSubmit={() => {}}
          onClear={() => setSearchQuery('')}
          placeholder="Search spare parts, laptops, phones…"
        />

        {/* Horizontal Category Quick Filter */}
        <CategoryChips
          selectedCategoryId={filters.categoryId}
          onSelectCategory={handleSelectCategory}
        />

        {/* Listings Feed */}
        {isLoading && listings.length === 0 ? (
          <View className="px-3 py-2 flex-row flex-wrap justify-between">
            {[1, 2, 3, 4].map((key) => (
              <View key={key} className="w-[48%]">
                <ListingSkeleton />
              </View>
            ))}
          </View>
        ) : (
          <FlatList
            data={listings}
            renderItem={renderItem}
            keyExtractor={keyExtractor}
            numColumns={2}
            columnWrapperStyle={{ justifyContent: 'space-between', gap: 10 }}
            contentContainerStyle={{ paddingHorizontal: 12, paddingTop: 10, paddingBottom: insets.bottom + 64 }}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
            scrollEventThrottle={16}
            removeClippedSubviews={true}
            windowSize={5}
            maxToRenderPerBatch={6}
            initialNumToRender={6}
            onEndReached={() => {
              if (hasNextPage && !isFetchingNextPage) {
                fetchNextPage();
              }
            }}
            onEndReachedThreshold={0.5}
            ListEmptyComponent={
              <EmptyState
                title="No Listings Found"
                description={
                  searchQuery.length > 0 || filters.categoryId || filters.locationId
                    ? 'No listings match your search or location. Try selecting another category or location.'
                    : 'Check back later for new items.'
                }
                icon="Search"
              />
            }
            refreshControl={
              <RefreshControl
                refreshing={isLoading && listings.length > 0}
                onRefresh={refetch}
                tintColor={base.brand[500]}
              />
            }
            ListFooterComponent={
              isFetchingNextPage ? (
                <View className="py-4">
                  <ListingSkeleton />
                </View>
              ) : null
            }
          />
        )}

        <LocationSelectorModal
          visible={isLocationModalOpen}
          onClose={() => setIsLocationModalOpen(false)}
          onSelectLocation={handleSelectLocation}
          selectedLocationId={filters.locationId}
        />
      </Container>
    </Screen>
  );
};

import RazorpayCheckout from 'react-native-razorpay';
import { Plan, PlansWalletV1DTO } from '@esparex/contracts';
import { apiClient } from '../../../infrastructure/api/apiClient';
import { PaymentOrder } from '../domain/PaymentOrder';
import { WalletSummary } from '../domain/WalletSummary';
import { PaymentTransaction } from '../domain/PaymentTransaction';
import { IPaymentRepository, VerifyPaymentInput, PaymentSuccessResult } from './IPaymentRepository';
import { CreatePaymentOrderMapper } from './mappers/CreatePaymentOrderMapper';

export class ApiPaymentRepository implements IPaymentRepository {
  async getPlans(): Promise<Plan[]> {
    const response = await apiClient.get<{ data: Plan[] }>('/payments/plans');
    const resData = response.data;
    if (Array.isArray(resData)) return resData;
    return resData?.data || [];
  }

  async createPaymentOrder(planId: string): Promise<PaymentOrder> {
    const payload = CreatePaymentOrderMapper.toPayload(planId);
    const response = await apiClient.post<{ data: PaymentOrder }>('/payments/orders', payload);
    return response.data.data;
  }

  async verifyPayment(input: VerifyPaymentInput): Promise<void> {
    try {
      await apiClient.post('/payments/verify', {
        razorpay_payment_id: input.razorpayPaymentId,
        razorpay_order_id: input.razorpayOrderId,
        razorpay_signature: input.razorpaySignature,
      });
    } catch (error: any) {
      // 🛡️ Webhook-Only Fallback: If backend verify endpoint returns 404 (e.g. server running in webhook-only mode),
      // client payment is confirmed asynchronously via gateway webhook to prevent blocking native UI checkout.
      if (error?.response?.status === 404) {
        return;
      }
      throw error;
    }
  }

  async openNativeCheckout(order: PaymentOrder): Promise<PaymentSuccessResult> {
    if (!RazorpayCheckout || typeof RazorpayCheckout.open !== 'function') {
      throw new Error('Native payment gateway is not available on this device platform. Please use Web or supported build.');
    }

    const options = {
      description: 'Ad Credits Package',
      currency: order.currency || 'INR',
      key: order.keyId || 'rzp_test_placeholder',
      amount: Math.round(order.amount * 100),
      name: 'Esparex',
      order_id: order.orderId,
      prefill: {
        email: order.userEmail || '',
        contact: order.userPhone || '',
        name: order.userName || 'Esparex User',
      },
      theme: { color: '#2563eb' },
    };

    try {
      const data = await RazorpayCheckout.open(options);
      return {
        razorpay_payment_id: data.razorpay_payment_id,
        razorpay_order_id: data.razorpay_order_id || order.orderId,
        razorpay_signature: data.razorpay_signature || '',
      };
    } catch (error: any) {
      const code = error?.code;
      const description = error?.description || 'Payment failed or was cancelled';
      if (code === 0) {
        throw new Error('Payment was cancelled by user');
      }
      throw new Error(description);
    }
  }

  async getWalletSummary(): Promise<WalletSummary> {
    const response = await apiClient.get<{ data: WalletSummary }>('/payments/credits/wallet');
    return response.data?.data ?? {
      adCredits: 0,
      spotlightCredits: 0,
      smartAlertSlots: 0,
    };
  }

  async getTransactionHistory(): Promise<PaymentTransaction[]> {
    const response = await apiClient.get<{ data: PaymentTransaction[] }>('/payments/history');
    const resData = response.data;
    if (Array.isArray(resData)) return resData;
    return resData?.data || [];
  }

  async getPlansWalletDashboard(): Promise<PlansWalletV1DTO | null> {
    try {
      const res = await apiClient.get<{ success?: boolean; data?: PlansWalletV1DTO }>('/payments/account/plans-wallet');
      if (res.data?.data) {
        return res.data.data;
      }
      return null;
    } catch {
      return null;
    }
  }
}

import React, { useState } from 'react';
import { View, ScrollView, Alert, ActivityIndicator, TouchableOpacity } from 'react-native';
import { Screen, Container, Card, AppButton, AppText, AppIcon } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import { Plan } from '@esparex/contracts';
import { usePaymentPlans } from '../hooks/usePaymentPlans';
import { useWalletSummary } from '../hooks/useWalletSummary';
import { useCheckoutPayment } from '../hooks/useCheckoutPayment';

interface PlanSelectionScreenProps {
  onSuccess?: () => void;
  onBack?: () => void;
}

export function PlanSelectionScreen({ onSuccess, onBack }: PlanSelectionScreenProps) {
  const { data: plans, isLoading: loadingPlans } = usePaymentPlans();
  const { data: wallet } = useWalletSummary();
  const checkoutMutation = useCheckoutPayment();
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null);

  const handlePurchase = (plan: Plan) => {
    setSelectedPlanId(plan.id);

    checkoutMutation.mutate(
      { plan },
      {
        onSuccess: (result) => {
          Alert.alert(
            'Payment Successful',
            `Payment ID: ${result.razorpay_payment_id}\nYour ad credits have been added to your wallet!`,
            [
              {
                text: 'OK',
                onPress: () => onSuccess && onSuccess(),
              },
            ]
          );
        },
        onError: (err: any) => {
          if (err?.message?.toLowerCase().includes('cancelled')) {
            return; // User cancelled — silent exit
          }
          Alert.alert('Checkout Failed', err?.message || 'Unable to complete payment order. Please try again.');
        },
      }
    );
  };

  return (
    <Screen className="flex-1 bg-slate-50 dark:bg-slate-950">
      <View className="flex-row items-center px-4 py-3.5 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
        {onBack && (
          <TouchableOpacity
            onPress={onBack}
            accessibilityLabel="Back to profile"
            accessibilityRole="button"
            className="mr-3 p-1"
          >
            <AppIcon name="ArrowLeft" size={20} color={base.brand[500]} />
          </TouchableOpacity>
        )}
        <AppText variant="h3" className="font-bold text-slate-900 dark:text-slate-100">
          Ad Credits & Wallet Plans
        </AppText>
      </View>

      <ScrollView className="flex-1">
        {/* Wallet Credit Badge Summary */}
        <Container className="p-4">
          <Card className="p-4 rounded-2xl bg-slate-800 dark:bg-slate-900 border-none">
            <AppText variant="caption" className="font-semibold text-slate-300 mb-3">
              Your Credit Balances
            </AppText>
            <View className="flex-row justify-between">
              <View className="items-center flex-1">
                <AppText variant="h2" className="font-extrabold text-white">
                  {wallet?.adCredits ?? 0}
                </AppText>
                <AppText variant="caption" className="text-slate-400 mt-0.5">
                  Ad Credits
                </AppText>
              </View>
              <View className="items-center flex-1">
                <AppText variant="h2" className="font-extrabold text-white">
                  {wallet?.spotlightCredits ?? 0}
                </AppText>
                <AppText variant="caption" className="text-slate-400 mt-0.5">
                  Spotlight
                </AppText>
              </View>
              <View className="items-center flex-1">
                <AppText variant="h2" className="font-extrabold text-white">
                  {wallet?.smartAlertSlots ?? 0}
                </AppText>
                <AppText variant="caption" className="text-slate-400 mt-0.5">
                  Alert Slots
                </AppText>
              </View>
            </View>
          </Card>
        </Container>

        {/* Plan Cards List */}
        <Container className="px-4 pb-6">
          <AppText variant="h4" className="font-bold text-slate-900 dark:text-slate-100 mb-3">
            Available Credit Packages
          </AppText>

          {loadingPlans && (
            <View className="p-8 items-center">
              <ActivityIndicator size="large" color="#0284c7" />
            </View>
          )}

          {plans && plans.length === 0 && (
            <Card className="p-5 rounded-xl bg-white dark:bg-slate-900 items-center border-slate-200 dark:border-slate-800">
              <AppText variant="body" className="text-slate-500 dark:text-slate-400">
                No active credit packages available right now.
              </AppText>
            </Card>
          )}

          {plans?.map((plan) => {
            const isProcessing = checkoutMutation.isPending && selectedPlanId === plan.id;
            return (
              <Card key={plan.id} className="p-4 rounded-2xl bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 mb-3">
                <View className="flex-row justify-between items-center mb-1.5">
                  <AppText variant="h4" className="font-bold text-slate-900 dark:text-slate-100">
                    {plan.name}
                  </AppText>
                  <AppText variant="h3" className="font-extrabold text-brand-600 dark:text-brand-400">
                    {plan.currency === 'INR' || !plan.currency ? '₹' : plan.currency}
                    {plan.price}
                  </AppText>
                </View>

                {plan.description && (
                  <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-2.5">
                    {plan.description}
                  </AppText>
                )}

                <View className="mb-3.5">
                  <AppText variant="caption" className="text-slate-700 dark:text-slate-300 mb-1">
                    ✓ {plan.credits} Listing Credits included
                  </AppText>
                  {plan.durationDays && (
                    <AppText variant="caption" className="text-slate-700 dark:text-slate-300 mb-1">
                      ✓ Valid for {plan.durationDays} days
                    </AppText>
                  )}
                </View>

                <AppButton
                  label={isProcessing ? 'Processing...' : 'Buy Package'}
                  onPress={() => handlePurchase(plan)}
                  disabled={isProcessing}
                  variant="primary"
                />
              </Card>
            );
          })}
        </Container>
      </ScrollView>
    </Screen>
  );
}

import { CreateListingRequest } from '@esparex/contracts';
import { PostAdDraft } from '../domain/PostAdDraft';
import { IListingRepository } from '../../listings/application/IListingRepository';
import { Listing } from '../../listings/domain/Listing';
import { IImageUploadService } from './IImageUploadService';
import { PostAdValidator } from './PostAdValidator';
import { PickedImage } from '../domain/PickedImage';
import { UploadedImage } from '../domain/UploadedImage';
import { CreateListingRequestMapper } from './mappers/CreateListingRequestMapper';

// ---------------------------------------------------------------------------
// Result types
// ---------------------------------------------------------------------------

/**
 * SubmitErrorKind — identifies which pipeline stage failed.
 *
 * Allows `useSubmitAd` and the UI to distinguish between:
 *   - validation failures (user must fix the draft)
 *   - upload failures   (retry is viable)
 *   - api failures      (retry is viable)
 */
export type SubmitErrorKind = 'validation' | 'upload' | 'api';

export interface SubmitError {
  kind: SubmitErrorKind;
  message: string;
}

/**
 * SubmitResult — discriminated union instead of exception-driven control flow.
 *
 * Callers pattern-match on `success` rather than catching thrown errors:
 *
 *   const result = await postAdService.submit(draft, onPhaseChange);
 *   if (result.success) { navigate(result.listingId); }
 *   else { showError(result.error); }
 */
export type SubmitResult =
  | { success: true; listingId: string }
  | { success: false; kind: SubmitErrorKind; message: string };

// ---------------------------------------------------------------------------
// Phase callback
// ---------------------------------------------------------------------------

/**
 * SubmitPhase — the current stage of a running submission.
 *
 * Passed to the optional `onPhaseChange` callback so callers can
 * display "Uploading photos…" and "Creating listing…" without the
 * service knowing about UI state.
 */
export type SubmitPhase = 'uploading' | 'creating';

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

/**
 * PostAdService — orchestrates the wizard-to-API submission pipeline.
 *
 * Responsibilities:
 *   1. Validate the draft is complete (PostAdValidator)
 *   2. Upload local images → receive cloud storage keys (IImageUploadService)
 *   3. Transform PostAdDraft (local state) into CreateListingRequest (API payload)
 *   4. Call IListingRepository.create() with the clean request
 *
 * Does NOT:
 *   - Mutate the original draft
 *   - Know about UI, navigation, or submission status
 *   - Throw exceptions for control flow — returns SubmitResult instead
 */
export class PostAdService {
  constructor(
    private readonly imageUploadService: IImageUploadService,
    private readonly listingRepository: IListingRepository,
  ) {}

  public async submit(
    draft: PostAdDraft,
    onPhaseChange?: (phase: SubmitPhase) => void,
  ): Promise<SubmitResult> {
    // 1. Validate — return structured error instead of throwing
    if (!PostAdValidator.isReadyToSubmit(draft)) {
      return {
        success: false,
        kind: 'validation',
        message: 'Please complete all required fields before submitting.',
      };
    }

    // 2. Upload images via IImageUploadService using PickedImage domain objects
    onPhaseChange?.('uploading');
    let uploadedImages: readonly UploadedImage[];
    try {
      const pickedImages: readonly PickedImage[] =
        draft.pickedImages && draft.pickedImages.length > 0
          ? draft.pickedImages
          : (draft.localImages ?? []).map((uri) => ({ uri }));
      uploadedImages = pickedImages.length
        ? await this.imageUploadService.uploadImages(pickedImages)
        : [];
    } catch (uploadErr) {
      const message =
        uploadErr instanceof Error ? uploadErr.message : 'Photo upload failed. Please try again.';
      return { success: false, kind: 'upload', message };
    }

    // 3. Build the API request via explicit CreateListingRequestMapper
    const request = CreateListingRequestMapper.fromDraft(draft, uploadedImages);

    // 4. Create the listing
    onPhaseChange?.('creating');
    let created: { id: string };
    try {
      created = await this.listingRepository.create(request);
    } catch (apiErr) {
      const message =
        apiErr instanceof Error ? apiErr.message : 'Could not create your listing. Please try again.';
      return { success: false, kind: 'api', message };
    }

    return { success: true, listingId: created.id };
  }
}

