import { useState, useEffect, useCallback } from 'react';
import { services } from '../../../../bootstrap';
import { CategoryOption } from '../../domain/CategoryOption';

export interface UseCategoriesResult {
  categories: readonly CategoryOption[];
  isLoading: boolean;
  error: Error | null;
  refetch: () => void;
}

/**
 * useCategories — presentation hook for fetching ad categories.
 *
 * Calls CategoryService from the bootstrap services, managing React state.
 * Accurately surfaces empty arrays or errors from the backend.
 */
export const useCategories = (): UseCategoriesResult => {
  const [categories, setCategories] = useState<readonly CategoryOption[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchCategories = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await services.categoryService.getCategories();
      setCategories(data);
    } catch (err) {
      const normalised = err instanceof Error ? err : new Error('Failed to load categories');
      setError(normalised);
      setCategories([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchCategories();
  }, [fetchCategories]);

  return {
    categories,
    isLoading,
    error,
    refetch: fetchCategories,
  };
};

import React, { useCallback } from 'react';
import { View, ScrollView, Alert, StyleSheet } from 'react-native';
import { AppText, Center, AppIcon } from '@esparex/mobile-ui';
import { MAX_AD_IMAGES } from '@esparex/contracts';
import { usePostAdDraft } from '../../usePostAdDraft';
import { ImageGrid, AddPhotoButton } from '../components/ImagePickerComponents';
import { services } from '../../../../bootstrap';

/**
 * StepImages — Step 3 of the Post Ad wizard (Photos & Final Step).
 *
 * Responsibilities:
 * - Read current localImages/pickedImages from draft
 * - Pick photos up to MAX_AD_IMAGES (5 photos)
 * - Show Cover badge on the primary photo
 * - Remove individual images
 */
export const StepImages = () => {
  const { state, setPickedImages, setImages } = usePostAdDraft();
  const images = state.draft.localImages ?? [];
  const pickedImages = state.draft.pickedImages ?? [];
  const canAddMore = images.length < MAX_AD_IMAGES;

  const processImageResult = useCallback(
    (result: Awaited<ReturnType<typeof services.imagePicker.pick>>) => {
      if (result.success) {
        const available = MAX_AD_IMAGES - images.length;
        const newPicked = result.images.slice(0, available);
        const combinedPicked = [...pickedImages, ...newPicked];
        setPickedImages(combinedPicked);
        setImages(combinedPicked.map((img) => img.uri));
      } else if (result.reason === 'permission-denied') {
        Alert.alert(
          'Permission Required',
          result.message || 'Camera or photo gallery access is required to add photos.'
        );
      } else if (result.reason === 'error') {
        Alert.alert('Image Selection Failed', result.message || 'Could not process photo.');
      }
    },
    [images.length, pickedImages, setPickedImages, setImages]
  );

  const handlePickFromGallery = useCallback(async () => {
    const result = await services.imagePicker.pick();
    processImageResult(result);
  }, [processImageResult]);

  const handleCaptureFromCamera = useCallback(async () => {
    const result = await services.imagePicker.captureFromCamera();
    processImageResult(result);
  }, [processImageResult]);

  const handleAdd = useCallback(() => {
    if (!canAddMore) return;
    Alert.alert('Add Photo', 'Choose how you want to add photos to your listing', [
      { text: 'Take Photo', onPress: () => void handleCaptureFromCamera() },
      { text: 'Choose from Gallery', onPress: () => void handlePickFromGallery() },
      { text: 'Cancel', style: 'cancel' },
    ]);
  }, [canAddMore, handleCaptureFromCamera, handlePickFromGallery]);

  const handleRemove = useCallback(
    (index: number) => {
      Alert.alert('Remove photo', 'Remove this photo from your listing?', [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Remove',
          style: 'destructive',
          onPress: () => {
            const updatedPicked = pickedImages.filter((_, i) => i !== index);
            setPickedImages(updatedPicked);
            setImages(updatedPicked.map((img) => img.uri));
          },
        },
      ]);
    },
    [pickedImages, setPickedImages, setImages]
  );

  return (
    <ScrollView
      className="flex-1"
      contentContainerStyle={styles.scrollContent}
      showsVerticalScrollIndicator={false}
    >
      <AppText variant="h3" className="text-slate-900 dark:text-white font-bold mb-1">
        Add Photos
      </AppText>
      <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-5">
        Listings with clear photos get up to 5x more responses. Add up to {MAX_AD_IMAGES} photos.
      </AppText>

      {/* Thumbnail grid + add button */}
      <View className="flex-row flex-wrap gap-2 mb-4">
        <ImageGrid images={[...images]} onRemove={handleRemove} />
        {canAddMore && <AddPhotoButton onPress={handleAdd} />}
      </View>

      {/* Guidance when no images added yet */}
      {images.length === 0 && (
        <Center className="py-8 bg-slate-50 dark:bg-slate-900/60 rounded-2xl border border-dashed border-slate-300 dark:border-slate-700 my-4">
          <AppIcon name="ImagePlus" size={40} color="#64748b" />
          <AppText variant="body" className="text-slate-600 dark:text-slate-300 font-semibold mt-3 text-center">
            Upload at least 1 photo
          </AppText>
          <AppText variant="caption" className="text-slate-400 text-center mt-1 px-6">
            The first photo will be shown as the primary cover photo for your ad.
          </AppText>
        </Center>
      )}

      {/* Count indicator */}
      {images.length > 0 && (
        <AppText variant="caption" className="text-slate-400 dark:text-slate-500 text-center font-medium mt-2">
          {images.length} of {MAX_AD_IMAGES} photos added (First image is Cover)
        </AppText>
      )}
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  scrollContent: { padding: 16, paddingBottom: 40 },
});

import React, { useState } from 'react';
import { Modal, View, TextInput, TouchableOpacity, Alert, ScrollView } from 'react-native';
import { AppButton, AppText } from '@esparex/mobile-ui';
import { SmartAlertFormState, INITIAL_SMART_ALERT_FORM_STATE } from '../../domain/SmartAlertFormState';
import { useCreateSmartAlert } from '../hooks/useCreateSmartAlert';
import { SmartAlert } from '../../domain/SmartAlert';

interface CreateSmartAlertModalProps {
  visible: boolean;
  onClose: () => void;
  initialAlert?: SmartAlert | null;
  onQuotaExceeded?: () => void;
}

export function CreateSmartAlertModal({
  visible,
  onClose,
  initialAlert,
  onQuotaExceeded,
}: CreateSmartAlertModalProps) {
  const [formState, setFormState] = useState<SmartAlertFormState>(INITIAL_SMART_ALERT_FORM_STATE);
  const createMutation = useCreateSmartAlert();

  React.useEffect(() => {
    if (initialAlert) {
      setFormState({
        name: initialAlert.name || '',
        keywords: initialAlert.criteria?.keywords || '',
        category: initialAlert.criteria?.category || '',
        minPrice: initialAlert.criteria?.minPrice ? String(initialAlert.criteria.minPrice) : '',
        maxPrice: initialAlert.criteria?.maxPrice ? String(initialAlert.criteria.maxPrice) : '',
        location: initialAlert.criteria?.location || '',
        radiusKm: initialAlert.radiusKm || 25,
        frequency: initialAlert.frequency || 'instant',
      });
    } else {
      setFormState(INITIAL_SMART_ALERT_FORM_STATE);
    }
  }, [initialAlert, visible]);

  const handleSubmit = () => {
    if (!formState.name.trim() && !formState.keywords.trim() && !formState.category.trim()) {
      Alert.alert('Validation Error', 'Please specify an alert name, search keyword, or category.');
      return;
    }

    if (formState.minPrice && formState.maxPrice) {
      const minP = parseFloat(formState.minPrice);
      const maxP = parseFloat(formState.maxPrice);
      if (maxP < minP) {
        Alert.alert('Validation Error', 'Maximum price must be greater than or equal to minimum price.');
        return;
      }
    }

    createMutation.mutate(formState, {
      onSuccess: () => {
        Alert.alert('Smart Alert Created', 'You will receive instant push notifications when matching ads are posted.');
        onClose();
      },
      onError: (err: any) => {
        if (err?.response?.status === 403 || err?.message?.includes('SMART_ALERT_LIMIT_EXCEEDED')) {
          Alert.alert(
            'Alert Limit Reached',
            'You have reached your smart alert quota limit. Upgrade your credit plan to create more alerts.',
            [
              { text: 'Cancel', style: 'cancel' },
              { text: 'Upgrade Plan', onPress: () => onQuotaExceeded && onQuotaExceeded() },
            ]
          );
        } else {
          Alert.alert('Creation Failed', err?.message || 'Unable to create smart alert. Please try again.');
        }
      },
    });
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent
      onRequestClose={onClose}
      accessibilityViewIsModal={true}
    >
      <View className="flex-1 bg-black/50 justify-end">
        <View className="bg-white dark:bg-slate-900 rounded-t-3xl p-5 max-h-[85%] border-t border-slate-200 dark:border-slate-800">
          <View className="flex-row justify-between items-center mb-4">
            <AppText variant="h3" className="font-bold text-slate-900 dark:text-slate-100">
              {initialAlert ? 'Edit Smart Alert' : 'Create Smart Alert'}
            </AppText>
            <TouchableOpacity
              onPress={onClose}
              accessibilityRole="button"
              accessibilityLabel="Close smart alert dialog"
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <AppText variant="body" className="font-semibold text-slate-500 dark:text-slate-400 text-lg">
                ✕
              </AppText>
            </TouchableOpacity>
          </View>

          <ScrollView className="mb-4" showsVerticalScrollIndicator={false}>
            <View className="mb-3.5">
              <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Alert Label *
              </AppText>
              <TextInput
                className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                placeholder="e.g. iPhone 13 in Mumbai"
                placeholderTextColor="#94a3b8"
                value={formState.name}
                onChangeText={(text) => setFormState((prev) => ({ ...prev, name: text }))}
              />
            </View>

            <View className="mb-3.5">
              <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Search Keyword
              </AppText>
              <TextInput
                className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                placeholder="e.g. OLED TV, Royal Enfield"
                placeholderTextColor="#94a3b8"
                value={formState.keywords}
                onChangeText={(text) => setFormState((prev) => ({ ...prev, keywords: text }))}
              />
            </View>

            <View className="mb-3.5">
              <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Category
              </AppText>
              <TextInput
                className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                placeholder="e.g. Mobile Phones, Electronics"
                placeholderTextColor="#94a3b8"
                value={formState.category}
                onChangeText={(text) => setFormState((prev) => ({ ...prev, category: text }))}
              />
            </View>

            <View className="flex-row justify-between mb-3.5">
              <View className="w-[48%]">
                <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                  Min Price (₹)
                </AppText>
                <TextInput
                  className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                  placeholder="Min"
                  placeholderTextColor="#94a3b8"
                  keyboardType="numeric"
                  value={formState.minPrice}
                  onChangeText={(text) => setFormState((prev) => ({ ...prev, minPrice: text }))}
                />
              </View>

              <View className="w-[48%]">
                <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                  Max Price (₹)
                </AppText>
                <TextInput
                  className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                  placeholder="Max"
                  placeholderTextColor="#94a3b8"
                  keyboardType="numeric"
                  value={formState.maxPrice}
                  onChangeText={(text) => setFormState((prev) => ({ ...prev, maxPrice: text }))}
                />
              </View>
            </View>

            <View className="mb-3.5">
              <AppText variant="caption" className="font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Location / City
              </AppText>
              <TextInput
                className="border border-slate-300 dark:border-slate-700 rounded-xl px-3 py-2.5 text-base text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950"
                placeholder="e.g. Mumbai, New Delhi"
                placeholderTextColor="#94a3b8"
                value={formState.location}
                onChangeText={(text) => setFormState((prev) => ({ ...prev, location: text }))}
              />
            </View>
          </ScrollView>

          <View className="pt-2">
            <AppButton
              label={createMutation.isPending ? 'Saving...' : 'Save Smart Alert'}
              onPress={handleSubmit}
              disabled={createMutation.isPending}
              className="bg-brand-600 hover:bg-brand-700"
            />
          </View>
        </View>
      </View>
    </Modal>
  );
}

