"use client";

import { useEffect, useCallback } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { AdPayloadSchema as postAdSchema, PartialAdPayloadSchema as partialAdSchema, AdPayload as PostAdFormData } from "@/schemas/adPayload.schema";
import { Resolver } from "react-hook-form";

const DRAFT_KEY = "esparex_post_ad_draft";

export function usePostAdForm(isEditMode: boolean = false) {
    // Initialize Form
    const form = useForm<PostAdFormData>({
        resolver: zodResolver(isEditMode ? partialAdSchema : postAdSchema) as Resolver<PostAdFormData>,
        mode: "all",
        shouldFocusError: true,
        defaultValues: {
            category: "",
            categoryId: "",
            brand: "",
            brandId: "",
            model: "",
            modelId: "",
            screenSize: "",

            title: "",
            description: "",
            images: [],
            price: undefined,
            isFree: false,
            location: { city: "" } as PostAdFormData["location"],
            spareParts: [],
            deviceCondition: undefined,
        }
    });

    const { register, control, handleSubmit, watch, setValue, trigger, formState: { errors } } = form;

    // Load draft on mount
    useEffect(() => {
        if (isEditMode) return;
        try {
            const draft = localStorage.getItem(DRAFT_KEY);
            if (draft) {
                const parsed = JSON.parse(draft);
                // Keep defaultValues structure but apply draft
                form.reset((prev) => ({ ...prev, ...parsed }));
            }
        } catch (e) {
            console.error("Failed to parse post ad draft", e);
        }
    }, [isEditMode, form]);

    // Save draft on change
    useEffect(() => {
        if (isEditMode) return;
        const subscription = watch((value) => {
            try {
                localStorage.setItem(DRAFT_KEY, JSON.stringify(value));
            } catch (e) {
                console.error("Failed to save post ad draft", e);
            }
        });
        return () => subscription.unsubscribe();
    }, [isEditMode, watch]);

    const clearDraft = useCallback(() => {
        if (isEditMode) return;
        localStorage.removeItem(DRAFT_KEY);
    }, [isEditMode]);

    return {
        form,
        register,
        control,
        errors,
        watch,
        setValue,
        trigger,
        handleSubmit,
        clearDraft,
    };
}

"use client";

import { useEffect, useState, useCallback } from "react";
import type { PostingEntitlementMatrixDTO, SingleEntitlementState } from "@esparex/contracts";
import { apiClient } from "@/lib/api/client";
import { unwrapApiPayload } from "@/lib/api/result";

type ModuleType = "ads" | "services" | "spareParts" | "smartAlerts";

export function usePostingEntitlement(moduleType?: ModuleType) {
  const [matrix, setMatrix] = useState<PostingEntitlementMatrixDTO | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchEntitlements = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const res = await apiClient.get<unknown>("entitlements/posting");
      const unwrapped = unwrapApiPayload<PostingEntitlementMatrixDTO>(res);
      if (unwrapped) {
        setMatrix(unwrapped);
      } else {
        setError("Failed to load posting entitlements");
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Error fetching entitlements";
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchEntitlements();
  }, [fetchEntitlements]);

  const activeEntitlement: SingleEntitlementState | null =
    matrix && moduleType ? matrix[moduleType] : null;

  return {
    matrix,
    entitlement: activeEntitlement,
    isAllowed: activeEntitlement ? activeEntitlement.allowed : true,
    isLoading,
    error,
    refetch: fetchEntitlements,
  };
}

